def test_low_stock_returns_products_strictly_below_threshold_sorted(shop):
    # Stock: BOOK 50, LAMP 5, PEN 100.
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 400, "on_hand": 5})
